  "auth.loginTab": { en: "Log in", sr: "Prijava", de: "Anmelden", fr: "Connexion", es: "Iniciar sesión", it: "Accedi", pt: "Entrar", nl: "Inloggen", pl: "Zaloguj się", ru: "Войти", uk: "Увійти", zh: "登录", ja: "ログイン", ko: "로그인", ar: "تسجيل الدخول", hi: "लॉग इन", tr: "Giriş yap", el: "Σύνδεση", sv: "Logga in", cs: "Přihlásit se", da: "Log ind", fi: "Kirjaudu sisään", no: "Logg inn", ro: "Conectare", hu: "Bejelentkezés", sk: "Prihlásiť sa", bg: "Вход" },
